// capability is what a Mod puts in the registry.
//
// It exists because converting to the interface at the registration call site
// does not do what it looks like it does: `Value: Rooms(x)` stores an any
// whose dynamic type is still x's — Go does not box an interface inside an
// interface — so an assertion on the concrete type succeeds anyway. Wrapping
// the interface in a struct makes the dynamic type this wrapper, which
// satisfies Rooms and nothing else.
//
// The consequence is the one that matters: a consumer cannot bind to the local
// implementation and then break on the day this service moves into its own
// process.
//
// It forwards each method explicitly rather than embedding the interface, and
// that is not style. Embedding names the field after the type, so an interface
// with a method of its own name — Rank.Rank, Match.Match — would have the
// field shadow the method and the wrapper would not satisfy the interface at
// all. The second service this generator ran against had exactly that shape.
type capability struct{ inner Rooms }

func (c capability) Describe(ctx context.Context) (string, error) {
	return c.inner.Describe(ctx)
}

func (c capability) Create(ctx context.Context, spec Spec) (Ref, error) {
	return c.inner.Create(ctx, spec)
}

func (c capability) Join(ctx context.Context, room Ref, binding Binding, bodyID uint64) (Member, error) {
	return c.inner.Join(ctx, room, binding, bodyID)
}

func (c capability) Submit(ctx context.Context, member Member, input Input) error {
	return c.inner.Submit(ctx, member, input)
}

func (c capability) Poll(ctx context.Context, member Member, ack uint64) (Delivery, error) {
	return c.inner.Poll(ctx, member, ack)
}

func (c capability) Leave(ctx context.Context, member Member) error {
	return c.inner.Leave(ctx, member)
}

func (c capability) Destroy(ctx context.Context, room Ref) error {
	return c.inner.Destroy(ctx, room)
}

// Capability wraps a Rooms for registration. Both Mods use it, so the
// capability's dynamic type is the same whichever process published it.
func Capability(service Rooms) Rooms { return capability{inner: service} }

